import 'dart:io';

import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:miarina_media/engine/engine_factory.dart';
import 'package:miarina_media/engine/media_engine.dart';

// Runs the platform engine for real (libmpv on Windows, Media3 on Android).
// Folder: test.mp3, test.flac, test.mp4, test.mkv, externe.srt, and
// chanson.flac with its chanson.lrc. Media generated by the POC script, folder passed with
// --dart-define=POC_MEDIA=<dir> (test.mp3, test.flac, test.mp4, test.mkv,
// externe.srt).
const _mediaDir = String.fromEnvironment('POC_MEDIA');

Future<PlaybackSnapshot> _until(
  MediaEngine e,
  bool Function(PlaybackSnapshot) ok, {
  Duration timeout = const Duration(seconds: 10),
}) async {
  final deadline = DateTime.now().add(timeout);
  while (DateTime.now().isBefore(deadline)) {
    if (ok(e.current)) return e.current;
    await Future<void>.delayed(const Duration(milliseconds: 50));
  }
  fail(
    'timeout; last state: ${e.current.status} pos=${e.current.position} '
    'dur=${e.current.duration} err=${e.current.error?.message}',
  );
}

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  initializeEngines();

  String media(String name) => '$_mediaDir/$name';
  bool isLang(String? code, String iso1) =>
      code == iso1 ||
      (code ?? '').startsWith(iso1) ||
      code == {'fr': 'fre', 'en': 'eng'}[iso1];

  late MediaEngine engine;
  setUp(() => engine = createPlatformEngine()!);
  tearDown(() => engine.dispose());

  Future<void> mountVideo(WidgetTester tester) => tester.pumpWidget(
    Directionality(
      textDirection: TextDirection.ltr,
      child: SizedBox(width: 640, height: 360, child: engine.buildVideoView()),
    ),
  );

  for (final name in ['test.mp3', 'test.flac']) {
    testWidgets('plays $name and reports position', (tester) async {
      expect(
        File(media(name)).existsSync(),
        isTrue,
        reason: 'missing ${media(name)}',
      );
      await engine.open(MediaSource.file(media(name)));
      final s = await _until(engine, (s) => s.duration > Duration.zero);
      expect(s.duration.inSeconds, inInclusiveRange(19, 21));
      await _until(
        engine,
        (s) => s.isPlaying && s.position > const Duration(milliseconds: 800),
      );
      expect(engine.current.hasVideo, isFalse);
      expect(engine.current.error, isNull);

      await engine.pause();
      await _until(engine, (s) => s.status == PlaybackStatus.paused);
      await engine.setVolume(0.5);
      await _until(engine, (s) => (s.volume - 0.5).abs() < 0.01);
    });
  }

  testWidgets('plays test.mp4 with a picture, seeks and changes speed', (
    tester,
  ) async {
    // The interface only mounts the picture once the engine says there is
    // one, so this must be known before any video view exists.
    await engine.open(MediaSource.file(media('test.mp4')));
    final s = await _until(
      engine,
      (s) => s.hasVideo && s.duration > Duration.zero,
    );
    expect(s.videoSize, const Size(1280, 720));
    await mountVideo(tester);

    await engine.seek(const Duration(seconds: 12));
    await _until(
      engine,
      (s) => s.position >= const Duration(milliseconds: 11500),
    );

    await engine.setSpeed(1.5);
    await _until(engine, (s) => s.speed == 1.5);
    await tester.pump(const Duration(milliseconds: 500));
  });

  testWidgets('test.mkv exposes two audio tracks and subtitles', (
    tester,
  ) async {
    await mountVideo(tester);
    await engine.open(MediaSource.file(media('test.mkv')));
    var s = await _until(
      engine,
      (s) =>
          s.audioTracks.length == 2 &&
          s.subtitleTracks.isNotEmpty &&
          s.hasVideo,
    );
    expect(s.videoSize, const Size(1920, 1080));
    expect(s.audioTracks.where((t) => isLang(t.language, 'fr')), hasLength(1));
    expect(s.audioTracks.where((t) => isLang(t.language, 'en')), hasLength(1));
    s = await _until(engine, (s) => s.selectedAudio != null);
    expect(s.audioTracks.map((t) => t.id), contains(s.selectedAudio));

    final english = s.audioTracks.firstWhere((t) => isLang(t.language, 'en'));
    await engine.selectAudioTrack(english.id);
    await _until(engine, (s) => s.selectedAudio == english.id);

    final embedded = s.subtitleTracks.first;
    await engine.selectSubtitleTrack(embedded.id);
    await _until(engine, (s) => s.selectedSubtitle == embedded.id);

    await engine.setSubtitleEnabled(false);
    await _until(
      engine,
      (s) => s.selectedSubtitle == null && !s.subtitlesEnabled,
    );
    await engine.setSubtitleEnabled(true);
    await _until(engine, (s) => s.selectedSubtitle == embedded.id);

    await engine.loadExternalSubtitle(Uri.file(media('externe.srt')));
    s = await _until(
      engine,
      (s) =>
          s.subtitleTracks.length == 2 &&
          s.selectedSubtitle != null &&
          s.selectedSubtitle != embedded.id,
    );
    expect(s.subtitleTracks.map((t) => t.id), contains(s.selectedSubtitle));
  });

  testWidgets('the equalizer applies without stopping playback', (
    tester,
  ) async {
    await engine.open(MediaSource.file(media('test.mp3')));
    await _until(engine, (s) => s.isPlaying && s.duration > Duration.zero);
    final applied = await engine.setEqualizer([6, 3, 0, -2, 0, -6]);
    expect(applied, anyOf(isTrue, isNull));
    final at = engine.current.position;
    await _until(
      engine,
      (s) => s.position > at + const Duration(milliseconds: 600),
    );
    expect(engine.current.error, isNull);
    expect(
      engine.current.isPlaying,
      isTrue,
      reason: 'still reported as playing',
    );
    expect(await engine.setEqualizer(null), anyOf(isTrue, isNull));
    await Future<void>.delayed(const Duration(milliseconds: 600));
    expect(engine.current.isPlaying, isTrue, reason: 'after the bypass too');
  });

  testWidgets('bypassing an already bypassed equalizer is harmless', (
    tester,
  ) async {
    await engine.setEqualizer(null);
    await engine.open(MediaSource.file(media('test.mp3')));
    await _until(engine, (s) => s.isPlaying && s.duration > Duration.zero);
    await engine.setEqualizer(null);
    await Future<void>.delayed(const Duration(milliseconds: 600));
    expect(engine.current.isPlaying, isTrue);
  });

  testWidgets('repeat one keeps playing past the end', (tester) async {
    await engine.setRepeatMode(RepeatSetting.one);
    await engine.open(MediaSource.file(media('test.mp3')));
    await _until(engine, (s) => s.duration > Duration.zero);
    await engine.seek(const Duration(seconds: 19));
    await _until(
      engine,
      (s) => s.position < const Duration(seconds: 3) && s.isPlaying,
      timeout: const Duration(seconds: 8),
    );
    expect(engine.current.status, isNot(PlaybackStatus.ended));
  });

  // chanson.flac has chanson.lrc next to it: mpv tries to auto-load it as
  // subtitles and reports an error before the file is ready; playback must
  // not look failed.
  testWidgets('a sidecar file mpv cannot load is not a playback error', (
    tester,
  ) async {
    await engine.open(MediaSource.file(media('chanson.flac')));
    final s = await _until(
      engine,
      (s) => s.isPlaying && s.position > const Duration(milliseconds: 500),
    );
    expect(s.status, PlaybackStatus.playing);
    expect(s.error?.recoverable ?? true, isTrue);
  });

  testWidgets('chapters of an audiobook are listed when supported', (
    tester,
  ) async {
    // chapitres.m4b: 30 s, chapters at 0, 10 and 20 s.
    await engine.open(MediaSource.file(media('chapitres.m4b')));
    await _until(engine, (s) => s.duration > Duration.zero);
    if (!engine.capabilities.chapters) {
      expect(engine.current.chapters, isEmpty);
      return;
    }
    final s = await _until(engine, (s) => s.chapters.length == 3);
    expect(
      [for (final c in s.chapters) c.title],
      ['Rappels', 'Algorithmes classiques', 'Questions'],
    );
    expect(s.chapters[1].start, const Duration(seconds: 10));
    expect(s.chapterAt(const Duration(seconds: 15)), 1);
  });

  testWidgets('a missing file ends in an error state, not a hang', (
    tester,
  ) async {
    await engine.open(MediaSource.file(media('introuvable.mp3')));
    final s = await _until(engine, (s) => s.status == PlaybackStatus.error);
    expect(s.error, isNotNull);
    expect(s.error!.recoverable, isFalse);
  });
}
